class Checkout
  STRATEGIES = {
    retail:    ->(qty) { qty * 9.99 },
    wholesale: ->(qty) { qty * 7.49 },
  }.freeze

  def initialize(strategy = :retail)
    @pricing = STRATEGIES.fetch(strategy)     # raises on an unknown strategy
  end

  def total(qty) = @pricing.call(qty)         # Context delegates to the lambda
end
